arguments.old:
// flexible detent leaf, south of gear 1, plus its reaching arm and bump.
// leaf: x 19..23, y 13.2..14.4 (0.6 clear of gear-1 tip circle), z 3..10
translate([x1 - 2, 13.2, plate_h]) cube([4, 1.2, 7]);
// arm at detent-flange height, reaching north to the flange edge
translate([x1 - 1.1, 14.4, 9.6]) cube([2.2, 5, 2.2]);
// support post so arm and leaf stay one body when printed alone
translate([x1 - 0.8, 15.9, plate_h]) cube([1.6, 0.9, 6]);
// bump: knob at the outer edge of the arm, at flange-notch radius
translate([x1, y_c - 10.6, 9.6]) cylinder(r = 0.8, h = 2.2, $fn = 24);

arguments.new:
// Flexible detent: an arc wall south-east of gear 1, inner radius
// 15.6 (0.6 clear of the gear-1 tip circle), standing on the plate
// up to flange height. A short arm at its south end reaches north
// at flange height and carries the bump. The wall flexes radially.
intersection() {
    difference() {
        translate([x1, y_c, plate_h]) cylinder(r = 17, h = 6.4, $fn = 72);
        translate([x1, y_c, plate_h - 1]) cylinder(r = 15.6, h = 8.4, $fn = 72);
    }
    translate([0, 0, plate_h]) linear_extrude(height = 6.4)
        polygon(points = [[x1, y_c],
                          [x1 + 20 * cos(-90), y_c + 20 * sin(-90)],
                          [x1 + 20 * cos(-32), y_c + 20 * sin(-32)]]);
}
// arm at flange height, from the wall (y 14) north to the rim (y 18)
translate([x1 - 0.7, 14, 9.4]) cube([1.4, 4, 1.5]);
// bump: half-round knob centred on the flange rim (radius 12 south),
// protruding 0.8 north of the rim line into a notch when one aligns
translate([x1, y_c - 12, 9.4]) cylinder(r = 0.8, h = 1.5, $fn = 24);
